#!/usr/bin/env bash
# Record this machine's dependency prefix in a project's ignored local config.
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
PREFIX="$("$ROOT/scripts/prefix.sh" native)"
PROJECT="${1:-$ROOT}"
FILE="$PROJECT/cabal.project.local"
[ -f "$PREFIX/lib/libflint.a" ] || { echo 'Run scripts/build-deps.sh native first.' >&2; exit 1; }
if [ -f "$FILE" ] && ! head -1 "$FILE" | grep -q 'Generated by flintell'; then
  echo "Refusing to overwrite existing $FILE; add include/lib dirs from $PREFIX manually." >&2
  exit 1
fi
cat > "$FILE" <<EOF
-- Generated by flintell scripts/configure-cabal.sh
package *
  extra-include-dirs: $PREFIX/include
  extra-lib-dirs: $PREFIX/lib
EOF
